<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue';
import { provideSidebarContext, useSidebarResize } from './provider';
import { useAccount } from 'dashboard/composables/useAccount';
import { useConfig } from 'dashboard/composables/useConfig';
import { useKbd } from 'dashboard/composables/utils/useKbd';
import { useMapGetter } from 'dashboard/composables/store';
import { useStore } from 'vuex';
import { useI18n } from 'vue-i18n';
import { useSidebarKeyboardShortcuts } from './useSidebarKeyboardShortcuts';
import { useEmitter } from 'dashboard/composables/emitter';
import { BUS_EVENTS } from 'shared/constants/busEvents';
import { vOnClickOutside } from '@vueuse/components';
import { FEATURE_FLAGS } from 'dashboard/featureFlags';
import { useWindowSize, useEventListener } from '@vueuse/core';

import Button from 'dashboard/components-next/button/Button.vue';
import SidebarGroup from './SidebarGroup.vue';
import SidebarProfileMenu from './SidebarProfileMenu.vue';
import SidebarChangelogCard from './SidebarChangelogCard.vue';
import SidebarChangelogButton from './SidebarChangelogButton.vue';
import SidebarAccountSwitcher from './SidebarAccountSwitcher.vue';
import Logo from 'next/icon/Logo.vue';
import ComposeConversation from 'dashboard/components-next/NewConversation/ComposeConversation.vue';
import wootConstants from 'dashboard/constants/globals';
import {
  SIDEBAR_LABEL_DEFINITIONS,
  findSidebarLabel,
} from '../../store/modules/labels';
import { buildConversationPrefetchViews } from './rottaPrefetch';

const props = defineProps({
  isMobileSidebarOpen: {
    type: Boolean,
    default: false,
  },
});

const emit = defineEmits([
  'closeKeyShortcutModal',
  'openKeyShortcutModal',
  'showCreateAccountModal',
  'closeMobileSidebar',
]);

const { accountScopedRoute, isOnChatwootCloud } = useAccount();
const { isEnterprise } = useConfig();
const store = useStore();

// Calls run on the enterprise-only API (cloud runs enterprise); hide the entry
// on community so it doesn't lead to a dashboard/CTA the backend can't serve.
const isCallsAvailable = computed(
  () => isOnChatwootCloud.value || isEnterprise
);
const searchShortcut = useKbd([`$mod`, 'k']);
const { t } = useI18n();

const isACustomBrandedInstance = useMapGetter(
  'globalConfig/isACustomBrandedInstance'
);
const isRTL = useMapGetter('accounts/isRTL');

const { width: windowWidth } = useWindowSize();
const isMobile = computed(() => windowWidth.value < 768);

const accountId = useMapGetter('getCurrentAccountId');
const currentUserId = useMapGetter('getCurrentUserID');
const isFeatureEnabledonAccount = useMapGetter(
  'accounts/isFeatureEnabledonAccount'
);

const hasAdvancedAssignment = computed(() => {
  return isFeatureEnabledonAccount.value(
    accountId.value,
    FEATURE_FLAGS.ADVANCED_ASSIGNMENT
  );
});

const hasConversationUnreadCounts = computed(() => {
  return isFeatureEnabledonAccount.value(
    accountId.value,
    FEATURE_FLAGS.CONVERSATION_UNREAD_COUNTS
  );
});

const hasDataImport = computed(() => {
  return isFeatureEnabledonAccount.value(
    accountId.value,
    FEATURE_FLAGS.DATA_IMPORT
  );
});

const fetchConversationUnreadCounts = ([currentAccountId, isEnabled]) => {
  if (!currentAccountId || !isEnabled) return;

  store.dispatch('conversationUnreadCounts/get');
};

const fetchSidebarSortPreferences = ([currentAccountId, userId]) => {
  if (!currentAccountId || !userId) return;
  store.dispatch('sidebarSortPreferences/initialize');
};

const toggleShortcutModalFn = show => {
  if (show) {
    emit('openKeyShortcutModal');
  } else {
    emit('closeKeyShortcutModal');
  }
};

useSidebarKeyboardShortcuts(toggleShortcutModalFn);

const expandedItem = ref(null);

const setExpandedItem = name => {
  expandedItem.value = expandedItem.value === name ? null : name;
};

const {
  sidebarWidth,
  isCollapsed,
  setSidebarWidth,
  saveWidth,
  snapToCollapsed,
  snapToExpanded,
  COLLAPSED_THRESHOLD,
} = useSidebarResize();

// On mobile, sidebar is always expanded (flyout mode)
const isEffectivelyCollapsed = computed(
  () => !isMobile.value && isCollapsed.value
);

const sidebarToggleLabel = computed(() =>
  isEffectivelyCollapsed.value
    ? 'Expandir barra lateral'
    : 'Recolher barra lateral'
);
const sidebarToggleIcon = computed(() =>
  isEffectivelyCollapsed.value
    ? 'i-lucide-panel-left-open'
    : 'i-lucide-panel-left-close'
);

const toggleSidebar = () => {
  if (isMobile.value) return;
  if (isEffectivelyCollapsed.value) snapToExpanded();
  else snapToCollapsed();
};

// Resize handle logic
const isResizing = ref(false);
const startX = ref(0);
const startWidth = ref(0);

provideSidebarContext({
  expandedItem,
  setExpandedItem,
  isCollapsed: isEffectivelyCollapsed,
  sidebarWidth,
  isResizing,
});

// Get clientX from mouse or touch event
const getClientX = event =>
  event.touches ? event.touches[0].clientX : event.clientX;

const onResizeStart = event => {
  isResizing.value = true;
  startX.value = getClientX(event);
  startWidth.value = sidebarWidth.value;
  Object.assign(document.body.style, {
    cursor: 'col-resize',
    userSelect: 'none',
  });
  // Prevent default to avoid scrolling on touch
  event.preventDefault();
};

const onResizeMove = event => {
  if (!isResizing.value) return;

  const delta = isRTL.value
    ? startX.value - getClientX(event)
    : getClientX(event) - startX.value;
  setSidebarWidth(startWidth.value + delta);
};

const onResizeEnd = () => {
  if (!isResizing.value) return;

  isResizing.value = false;
  Object.assign(document.body.style, { cursor: '', userSelect: '' });

  // Snap to collapsed state if below threshold
  if (sidebarWidth.value < COLLAPSED_THRESHOLD) {
    snapToCollapsed();
  } else {
    saveWidth();
  }
};

const onResizeHandleDoubleClick = () => {
  if (isCollapsed.value) snapToExpanded();
  else snapToCollapsed();
};

// Support both mouse and touch events
useEventListener(document, 'mousemove', onResizeMove);
useEventListener(document, 'mouseup', onResizeEnd);
useEventListener(document, 'touchmove', onResizeMove, { passive: false });
useEventListener(document, 'touchend', onResizeEnd);

const labels = useMapGetter('labels/getLabelsOnSidebar');
const allLabels = useMapGetter('labels/getLabels');
const allUnreadCount = useMapGetter(
  'conversationUnreadCounts/getAllUnreadCount'
);
const getSidebarLabelCount = useMapGetter('labels/getSidebarLabelCount');
const archivedUnreadCount = useMapGetter(
  'conversationUnreadCounts/getArchivedUnreadCount'
);

const budgetLabelDefinition = SIDEBAR_LABEL_DEFINITIONS[0];
const caioAttentionLabelDefinition = SIDEBAR_LABEL_DEFINITIONS[1];
const closedClientsLabelDefinition = SIDEBAR_LABEL_DEFINITIONS[2];

const getSidebarLabelTitle = definition =>
  findSidebarLabel(allLabels.value, definition)?.title ||
  definition.fallbackTitle;

const budgetLabelTitle = computed(() =>
  getSidebarLabelTitle(budgetLabelDefinition)
);
const caioAttentionLabelTitle = computed(() =>
  getSidebarLabelTitle(caioAttentionLabelDefinition)
);
const closedClientsLabelTitle = computed(() =>
  getSidebarLabelTitle(closedClientsLabelDefinition)
);

const refreshSidebarLabelCounts = () => {
  if (!accountId.value) return;
  store.dispatch('labels/getSidebarCounts');
};

useEmitter('fetch_conversation_stats', refreshSidebarLabelCounts);
useEmitter('fetch_conversation_stats', () => {
  fetchConversationUnreadCounts([
    accountId.value,
    hasConversationUnreadCounts.value,
  ]);
});
useEmitter(BUS_EVENTS.ROTTA_FOLLOW_UP_REFRESH, refreshSidebarLabelCounts);
useEmitter(BUS_EVENTS.WEBSOCKET_RECONNECT_COMPLETED, refreshSidebarLabelCounts);

let sidebarLabelCountsRefreshTimer;

onMounted(() => {
  store.dispatch('labels/get', { forceNetwork: true });
  store.dispatch('notifications/unReadCount');
  store.dispatch('attributes/get');
  sidebarLabelCountsRefreshTimer = setInterval(
    refreshSidebarLabelCounts,
    10000
  );
});

onBeforeUnmount(() => {
  if (sidebarLabelCountsRefreshTimer) {
    clearInterval(sidebarLabelCountsRefreshTimer);
  }
});

watch([accountId, hasConversationUnreadCounts], fetchConversationUnreadCounts, {
  immediate: true,
});

watch([accountId, currentUserId], fetchSidebarSortPreferences, {
  immediate: true,
});

watch(
  [accountId, allLabels],
  ([currentAccountId, currentLabels]) => {
    if (!currentAccountId || !currentLabels.length) return;
    refreshSidebarLabelCounts();
  },
  { immediate: true }
);

const prefetchSignature = ref('');

const prefetchConversationViews = () => {
  if (!accountId.value || !labels.value.length) return;

  const common = {
    assigneeType: wootConstants.ASSIGNEE_TYPE.ALL,
    status: wootConstants.STATUS_TYPE.ALL,
    sortBy: wootConstants.SORT_BY_TYPE.LAST_ACTIVITY_AT_DESC,
    page: 1,
  };

  const sidebarLabelTitles = SIDEBAR_LABEL_DEFINITIONS.map(
    definition => findSidebarLabel(allLabels.value, definition)?.title
  )
    .filter(Boolean)
    .filter((title, index, titles) => titles.indexOf(title) === index);

  const views = buildConversationPrefetchViews({
    common,
    unreadConversationType: wootConstants.CONVERSATION_TYPE.UNREAD,
    priorityConversationType: wootConstants.CONVERSATION_TYPE.PRIORITY,
    archivedConversationType: wootConstants.CONVERSATION_TYPE.ARCHIVED,
    sidebarLabelTitles,
  });

  store.dispatch('prefetchConversationViews', views);
};

watch(
  [accountId, labels],
  ([currentAccountId, currentLabels]) => {
    if (!currentAccountId || !currentLabels.length) return;
    const signature = `${currentAccountId}:${currentLabels
      .map(label => label.title)
      .sort()
      .join('|')}`;
    if (signature === prefetchSignature.value) return;
    prefetchSignature.value = signature;
    prefetchConversationViews();
  },
  { immediate: true }
);

const closeMobileSidebar = () => {
  if (!props.isMobileSidebarOpen) return;
  emit('closeMobileSidebar');
};

const newReportRoutes = () => [
  {
    name: 'Reports Agent',
    label: t('SIDEBAR.REPORTS_AGENT'),
    to: accountScopedRoute('agent_reports_index'),
    activeOn: ['agent_reports_show'],
  },
  {
    name: 'Reports Label',
    label: t('SIDEBAR.REPORTS_LABEL'),
    to: accountScopedRoute('label_reports_index'),
  },
  {
    name: 'Reports Inbox',
    label: t('SIDEBAR.REPORTS_INBOX'),
    to: accountScopedRoute('inbox_reports_index'),
    activeOn: ['inbox_reports_show'],
  },
];

const reportRoutes = computed(() => newReportRoutes());

const menuItems = computed(() => {
  return [
    {
      name: 'Conversation',
      label: 'Conversas',
      icon: 'i-lucide-message-circle',
      children: [
        {
          name: 'All',
          label: 'Todos',
          icon: 'i-lucide-inbox',
          badgeCount: allUnreadCount.value,
          activeOn: ['inbox_conversation'],
          to: accountScopedRoute('home'),
        },
        {
          name: 'Unread',
          label: 'Não lidas',
          icon: 'i-lucide-mail-open',
          badgeCount: allUnreadCount.value,
          activeOn: ['conversation_unread', 'conversation_through_unread'],
          to: accountScopedRoute('conversation_unread'),
        },
        {
          name: 'Archived',
          label: 'Arquivados',
          icon: 'i-lucide-archive',
          color: '#dc2626',
          activeOn: ['archived_conversations', 'archived_conversation'],
          to: accountScopedRoute('archived_conversations'),
          badgeCount: archivedUnreadCount.value,
        },
        {
          name: 'Budgets',
          label: 'ORÇAMENTOS',
          icon: 'i-lucide-clipboard-list',
          color: budgetLabelDefinition.color,
          to: accountScopedRoute('label_conversations', {
            label: budgetLabelTitle.value,
          }),
          activeOn: ['label_conversations', 'conversations_through_label'],
          badgeCount: getSidebarLabelCount.value('budget'),
        },
        {
          name: 'CaioAttention',
          label: 'Caio Atenção',
          icon: 'i-lucide-bell-ring',
          color: caioAttentionLabelDefinition.color,
          to: accountScopedRoute('label_conversations', {
            label: caioAttentionLabelTitle.value,
          }),
          activeOn: ['label_conversations', 'conversations_through_label'],
          badgeCount: getSidebarLabelCount.value('caioAttention'),
        },
        {
          name: 'ClosedClients',
          label: 'Clientes Fechados',
          icon: 'i-lucide-badge-check',
          color: closedClientsLabelDefinition.color,
          to: accountScopedRoute('label_conversations', {
            label: closedClientsLabelTitle.value,
          }),
          activeOn: ['label_conversations', 'conversations_through_label'],
          badgeCount: getSidebarLabelCount.value('closedClients'),
        },
      ],
    },
    {
      name: 'Follow-up',
      label: 'Follow-up',
      icon: 'i-lucide-clock-3',
      to: accountScopedRoute('rotta_follow_up'),
      activeOn: ['rotta_follow_up'],
    },
    {
      name: 'Labels',
      label: 'Etiquetas',
      icon: 'i-lucide-tags',
      to: accountScopedRoute('labels_list'),
      activeOn: ['labels_list', 'labels_wrapper'],
    },
    ...(isCallsAvailable.value
      ? [
          {
            name: 'Calls',
            label: t('SIDEBAR.CALLS'),
            icon: 'i-lucide-phone',
            to: accountScopedRoute('calls_dashboard_index'),
            activeOn: ['calls_dashboard_index'],
          },
        ]
      : []),
    {
      name: 'Companies',
      label: t('SIDEBAR.COMPANIES'),
      icon: 'i-lucide-building-2',
      children: [
        {
          name: 'All Companies',
          label: t('SIDEBAR.ALL_COMPANIES'),
          to: accountScopedRoute(
            'companies_dashboard_index',
            {},
            { page: 1, search: undefined }
          ),
          activeOn: ['companies_dashboard_index', 'companies_dashboard_show'],
        },
      ],
    },
    {
      name: 'Reports',
      label: t('SIDEBAR.REPORTS'),
      icon: 'i-lucide-chart-spline',
      children: [
        {
          name: 'Report Overview',
          label: t('SIDEBAR.REPORTS_OVERVIEW'),
          to: accountScopedRoute('account_overview_reports'),
        },
        {
          name: 'Report Conversation',
          label: t('SIDEBAR.REPORTS_CONVERSATION'),
          to: accountScopedRoute('conversation_reports'),
        },
        ...reportRoutes.value,
      ],
    },
    {
      name: 'Settings',
      label: t('SIDEBAR.SETTINGS'),
      icon: 'i-lucide-bolt',
      children: [
        {
          name: 'Settings Account Settings',
          label: t('SIDEBAR.ACCOUNT_SETTINGS'),
          icon: 'i-lucide-briefcase',
          to: accountScopedRoute('general_settings_index'),
        },
        // {
        //   name: 'Settings Captain',
        //   label: t('SIDEBAR.CAPTAIN_AI'),
        //   icon: 'i-woot-captain',
        //   to: accountScopedRoute('captain_settings_index'),
        // },
        {
          name: 'Settings Agents',
          label: t('SIDEBAR.AGENTS'),
          icon: 'i-lucide-square-user',
          to: accountScopedRoute('agent_list'),
        },
        ...(hasAdvancedAssignment.value
          ? [
              {
                name: 'Settings Agent Assignment',
                label: t('SIDEBAR.AGENT_ASSIGNMENT'),
                icon: 'i-lucide-user-cog',
                activeOn: [
                  'assignment_policy_index',
                  'agent_assignment_policy_index',
                  'agent_assignment_policy_create',
                  'agent_assignment_policy_edit',
                  'agent_capacity_policy_index',
                  'agent_capacity_policy_create',
                  'agent_capacity_policy_edit',
                ],
                to: accountScopedRoute('assignment_policy_index'),
              },
            ]
          : []),
        {
          name: 'Settings Inboxes',
          label: t('SIDEBAR.INBOXES'),
          icon: 'i-lucide-inbox',
          activeOn: [
            'settings_inbox_list',
            'settings_inbox_show',
            'settings_inbox_new',
            'settings_inbox_finish',
            'settings_inboxes_page_channel',
            'settings_inboxes_add_agents',
          ],
          to: accountScopedRoute('settings_inbox_list'),
        },
        {
          name: 'Settings Labels',
          label: t('SIDEBAR.LABELS'),
          icon: 'i-lucide-tags',
          to: accountScopedRoute('labels_list'),
        },
        {
          name: 'Settings Integrations',
          label: t('SIDEBAR.INTEGRATIONS'),
          icon: 'i-lucide-blocks',
          to: accountScopedRoute('settings_applications'),
        },
        ...(hasDataImport.value
          ? [
              {
                name: 'Settings Data',
                label: t('SIDEBAR.DATA'),
                icon: 'i-lucide-database',
                to: accountScopedRoute('settings_data_imports'),
              },
            ]
          : []),
        {
          name: 'Settings Audit Logs',
          label: t('SIDEBAR.AUDIT_LOGS'),
          icon: 'i-lucide-briefcase',
          to: accountScopedRoute('auditlogs_list'),
        },
        {
          name: 'Settings Billing',
          label: t('SIDEBAR.BILLING'),
          icon: 'i-lucide-credit-card',
          to: accountScopedRoute('billing_settings_index'),
        },
      ],
    },
  ];
});
</script>

<template>
  <aside
    v-on-click-outside="[
      closeMobileSidebar,
      {
        ignore: [
          '#mobile-sidebar-launcher',
          '[data-popover-content]',
          '[data-popover-backdrop]',
        ],
      },
    ]"
    class="bg-n-background flex flex-col text-sm pb-px fixed top-0 ltr:left-0 rtl:right-0 h-full z-40 w-[200px] md:w-auto md:relative md:flex-shrink-0 md:ltr:translate-x-0 md:rtl:translate-x-0 ltr:border-r rtl:border-l border-n-weak"
    :class="[
      {
        'shadow-lg md:shadow-none': isMobileSidebarOpen,
        'ltr:-translate-x-full rtl:translate-x-full': !isMobileSidebarOpen,
        'transition-transform duration-200 ease-out md:transition-[width]':
          !isResizing,
      },
    ]"
    :style="isMobile ? undefined : { width: `${sidebarWidth}px` }"
  >
    <section
      class="grid"
      :class="isEffectivelyCollapsed ? 'mt-3 mb-6 gap-4' : 'mt-1 mb-4 gap-2'"
    >
      <div
        class="flex gap-2 items-center min-w-0"
        :class="{
          'justify-center px-1': isEffectivelyCollapsed,
          'px-2': !isEffectivelyCollapsed,
        }"
      >
        <template v-if="isEffectivelyCollapsed">
          <SidebarAccountSwitcher
            is-collapsed
            @show-create-account-modal="emit('showCreateAccountModal')"
          />
        </template>
        <template v-else>
          <div class="grid flex-shrink-0 place-content-center size-6">
            <Logo class="size-4" />
          </div>
          <div class="flex-shrink-0 w-px h-3 bg-n-strong" />
          <SidebarAccountSwitcher
            class="flex-grow -mx-1 min-w-0"
            @show-create-account-modal="emit('showCreateAccountModal')"
          />
        </template>
      </div>
      <div
        class="flex gap-2"
        :class="isEffectivelyCollapsed ? 'flex-col items-center' : 'px-2'"
      >
        <RouterLink
          v-if="!isEffectivelyCollapsed"
          :to="{ name: 'search' }"
          class="flex gap-2 items-center px-2 py-1 w-full h-7 rounded-lg outline outline-1 outline-n-weak bg-n-button-color transition-all duration-100 ease-out"
        >
          <span class="flex-shrink-0 i-lucide-search size-4 text-n-slate-10" />
          <span class="flex-grow text-start text-n-slate-10">
            {{ t('COMBOBOX.SEARCH_PLACEHOLDER') }}
          </span>
          <span
            class="hidden tracking-wide pointer-events-none select-none text-n-slate-10"
          >
            {{ searchShortcut }}
          </span>
        </RouterLink>
        <RouterLink
          v-else
          :to="{ name: 'search' }"
          class="flex items-center justify-center size-8 rounded-lg outline outline-1 outline-n-weak bg-n-button-color transition-all duration-100 ease-out hover:bg-n-alpha-2 dark:hover:bg-n-slate-9/30"
          :title="t('COMBOBOX.SEARCH_PLACEHOLDER')"
        >
          <span class="i-lucide-search size-4 text-n-slate-11" />
        </RouterLink>
        <ComposeConversation align="start">
          <template #trigger="{ isOpen }">
            <Button
              icon="i-lucide-pen-line"
              color="slate"
              size="sm"
              class="dark:hover:!bg-n-slate-9/30"
              :class="[
                isEffectivelyCollapsed
                  ? '!size-8 !outline-n-weak !text-n-slate-11'
                  : '!h-7 !outline-n-weak !text-n-slate-11',
                { '!bg-n-alpha-2 dark:!bg-n-slate-9/30': isOpen },
              ]"
            />
          </template>
        </ComposeConversation>
      </div>
    </section>
    <nav
      class="grid overflow-y-scroll flex-grow gap-2 pb-5 no-scrollbar min-w-0"
      :class="isEffectivelyCollapsed ? 'px-1' : 'px-2'"
    >
      <ul
        class="flex flex-col gap-1 m-0 list-none min-w-0"
        :class="{ 'items-center': isEffectivelyCollapsed }"
      >
        <SidebarGroup
          v-for="item in menuItems"
          :key="item.name"
          v-bind="item"
        />
      </ul>
    </nav>
    <section
      class="flex relative flex-col flex-shrink-0 gap-1 justify-between items-center"
    >
      <div
        class="pointer-events-none absolute inset-x-0 -top-[1.938rem] h-8 bg-gradient-to-t from-n-background to-transparent"
      />
      <SidebarChangelogCard
        v-if="
          isOnChatwootCloud &&
          !isACustomBrandedInstance &&
          !isEffectivelyCollapsed
        "
      />
      <SidebarChangelogButton
        v-if="
          isOnChatwootCloud &&
          !isACustomBrandedInstance &&
          isEffectivelyCollapsed
        "
      />
      <div
        class="px-1 py-1.5 flex-shrink-0 flex w-full z-50 gap-2 items-center border-t border-n-weak shadow-[0px_-2px_4px_0px_rgba(27,28,29,0.02)]"
        :class="isEffectivelyCollapsed ? 'justify-center' : 'justify-between'"
      >
        <SidebarProfileMenu
          :is-collapsed="isEffectivelyCollapsed"
          @open-key-shortcut-modal="emit('openKeyShortcutModal')"
        />
      </div>
    </section>
    <button
      v-if="!isMobile"
      type="button"
      class="rotta-sidebar-toggle"
      data-testid="sidebar-toggle"
      :aria-label="sidebarToggleLabel"
      :aria-expanded="!isEffectivelyCollapsed"
      :title="sidebarToggleLabel"
      @click="toggleSidebar"
    >
      <span :class="sidebarToggleIcon" aria-hidden="true" />
    </button>
    <!-- Resize Handle (desktop only) -->
    <div
      class="hidden md:block absolute top-0 h-full w-1 cursor-col-resize z-40 ltr:right-0 rtl:left-0 group"
      @mousedown="onResizeStart"
      @touchstart="onResizeStart"
      @dblclick="onResizeHandleDoubleClick"
    >
      <div
        class="absolute top-0 h-full w-px ltr:right-0 rtl:left-0 bg-transparent group-hover:bg-n-brand transition-colors"
        :class="{ 'bg-n-brand': isResizing }"
      />
    </div>
  </aside>
</template>

<style scoped>
.rotta-sidebar-toggle {
  position: absolute;
  inset-block-start: 4.35rem;
  inset-inline-end: -0.75rem;
  z-index: 45;
  display: grid;
  width: 1.5rem;
  height: 1.5rem;
  place-items: center;
  @apply text-n-slate-11 bg-n-surface-1 border border-n-weak;
  border-radius: 999px;
  box-shadow: 0 2px 8px rgb(15 23 42 / 12%);
  transition:
    color 120ms ease,
    background-color 120ms ease,
    box-shadow 120ms ease;
}

.rotta-sidebar-toggle:hover {
  @apply text-n-slate-12 bg-n-alpha-2;
  box-shadow: 0 3px 10px rgb(15 23 42 / 16%);
